<?php $title='Dashboard';require '_head.php';$counts=[];foreach(['products'=>'Produk','categories'=>'Kategori','banners'=>'Banner','portfolio'=>'Portfolio'] as $t=>$label)$counts[$label]=$pdo->query("SELECT COUNT(*) FROM $t")->fetchColumn();?><h1>Dashboard</h1><div class="grid"><?php foreach($counts as $k=>$v):?><div class="card"><small><?=e($k)?></small><h2><?=e($v)?></h2></div><?php endforeach;?></div><div class="panel"><h2>Mulai mengelola website</h2><p>Upload foto dan isi konten dari menu di atas. Harga dan keterangan produk boleh dikosongkan.</p></div><?php require '_foot.php';?>